const __pageData = JSON.parse('{"title":"Week 9 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-09.md","filePath":"solutions/week-09.md"}');
